text = "Zsmxsm sc sx Zyvilsec Zvkjk."
for shift in range(1,26):
    out = []
    for ch in text:
        if ch.isalpha():
            base = ord('A') if ch.isupper() else ord('a')
            out.append(chr((ord(ch)-base-shift)%26 + base))
        else:
            out.append(ch)
    print(f"Shift {shift}: {''.join(out)}")
